package envdoc

import (
	"strconv"
	"strings"

	"github.com/stergiotis/boxer/public/config/env"
)

// RenderKnownNames renders the Go source of the env package's knownNames:
// every variable the linked registry declares, sorted. A process that links
// only part of the repository checks a set variable against it, so a name
// another of the repository's binaries declares is not reported as
// unregistered (env.CheckEnviron).
func RenderKnownNames() (out []byte) {
	var b strings.Builder
	b.WriteString("// Code generated by public/app env gen-docs --known. DO NOT EDIT.\n\n")
	b.WriteString("package env\n\n")
	b.WriteString("// knownNames is every variable the repository's registry declares, sorted.\n")
	b.WriteString("var knownNames = []string{\n")
	for _, s := range env.Snapshot() {
		b.WriteString("\t" + strconv.Quote(s.Name) + ",\n")
	}
	b.WriteString("}\n")
	return []byte(b.String())
}
